import os,re,collections
mods={}
for dp,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): mods[os.path.join(dp,f)[:-5].replace('/','.')]=os.path.join(dp,f)
mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)',re.M)
dangling=[]
edges={}
for m,p in mods.items():
    ims=imp.findall(open(p,encoding='utf-8',errors='replace').read())
    proj=[x for x in ims if x.startswith('AlgebraicJacobian')]
    for x in proj:
        if x not in mods: dangling.append((m,x))
    edges[m]=[x for x in proj if x in mods]
print("DANGLING project imports:",len(dangling))
for a,b in dangling: print("   ",a,"->",b)
# cycle detect
WHITE,GRAY,BLACK=0,1,2
col=collections.defaultdict(int); cyc=[]
def dfs(u,stack):
    col[u]=GRAY; stack.append(u)
    for v in edges.get(u,[]):
        if col[v]==GRAY: cyc.append(stack[stack.index(v):]+[v])
        elif col[v]==WHITE: dfs(v,stack)
    stack.pop(); col[u]=BLACK
for m in mods:
    if col[m]==WHITE: dfs(m,[])
print("IMPORT CYCLES:",len(cyc))
for c in cyc[:5]: print("   ",' -> '.join(c))
